import base64
import io
import os
from typing import Any, Dict, List, Union

from google.cloud import vision


def detect_text_in_image(image: Union[str, bytes, bytearray, io.BytesIO]) -> Dict[str, Any]:
    client = vision.ImageAnnotatorClient()

    if isinstance(image, str):
        with open(image, "rb") as f:
            content = f.read()
    elif isinstance(image, io.BytesIO):
        content = image.getvalue()
    else:
        content = bytes(image)

    gimage = vision.Image(content=content)
    response = client.text_detection(image=gimage)

    texts: List[Dict[str, Any]] = []
    for annotation in response.text_annotations[1:]:
        vertices = []
        for v in annotation.bounding_poly.vertices:
            vertices.append({"x": getattr(v, "x", None), "y": getattr(v, "y", None)})
        texts.append(
            {
                "text": annotation.description,
                "confidence": getattr(annotation, "score", None),
                "bounding_poly": vertices,
            }
        )

    full_text = response.text_annotations[0].description if response.text_annotations else ""

    result = {
        "full_text": full_text,
        "detections": texts,
    }

    if response.error and response.error.message:
        result["error"] = response.error.message

    return result
